const StorageKey = "app-theme";
const AccentKey = "app-accent-color";

// Listeners: Map<id, DotNetObjectReference>
const _listeners = new Map();
let _nextId = 0;

function applyToDom(theme, accentColor) {
    const html = document.documentElement;
    html.setAttribute("data-theme", theme ?? "System");
    if (accentColor) {
        html.style.setProperty("--accent-color", accentColor);
    } else {
        html.style.removeProperty("--accent-color");
    }
}

export function getTheme() {
    return localStorage.getItem(StorageKey) ?? "System";
}

export function getAccentColor() {
    return localStorage.getItem(AccentKey) ?? "";
}

export function setTheme(theme, accentColor) {
    localStorage.setItem(StorageKey, theme);
    if (accentColor !== null && accentColor !== undefined) {
        localStorage.setItem(AccentKey, accentColor);
    }
    applyToDom(theme, accentColor ?? localStorage.getItem(AccentKey));
    notifyListeners(theme, accentColor ?? localStorage.getItem(AccentKey) ?? "");
}

function notifyListeners(theme, accentColor) {
    for (const [, ref] of _listeners) {
        try {
            ref.invokeMethodAsync("OnThemeChangedFromJs", theme, accentColor);
        } catch { /* listener disposed */ }
    }
}

export function addListener(dotNetRef) {
    const id = _nextId++;
    _listeners.set(id, dotNetRef);
    return id;
}

export function removeListener(id) {
    const ref = _listeners.get(id);
    if (ref) {
        _listeners.delete(id);
    }
}

// Apply saved theme on load (before any component renders)
applyToDom(getTheme(), localStorage.getItem(AccentKey));

// Sync across tabs via storage event
window.addEventListener("storage", (e) => {
    if (e.key === StorageKey || e.key === AccentKey) {
        const theme = localStorage.getItem(StorageKey) ?? "System";
        const accent = localStorage.getItem(AccentKey) ?? "";
        applyToDom(theme, accent);
        notifyListeners(theme, accent);
    }
});

using Microsoft.JSInterop;

namespace sv_4f0c5c4cc3a34996bb0854f218bf0efc.Services;

public enum Theme { Light, Dark, System }

/// <summary>
/// Scoped service that wraps JS-based theme state.
/// Each interactive circuit gets its own instance, but the JS module
/// is the single source of truth shared across all circuits in the browser.
/// </summary>
public sealed class ThemeService : IAsyncDisposable
{
    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;
    private DotNetObjectReference<ThemeService>? _selfRef;
    private int _listenerId = -1;

    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "";

    public event Action? OnChange;

    public ThemeService(IJSRuntime js) => _js = js;

    public async Task InitializeAsync()
    {
        _module = await _js.InvokeAsync<IJSObjectReference>(
            "import", "./js/theme-interop.js");

        var themeName = await _module.InvokeAsync<string>("getTheme");
        CurrentTheme = Enum.TryParse<Theme>(themeName, true, out var t) ? t : Theme.System;
        AccentColor = await _module.InvokeAsync<string>("getAccentColor");

        _selfRef = DotNetObjectReference.Create(this);
        _listenerId = await _module.InvokeAsync<int>("addListener", _selfRef);
    }

    public async Task SetThemeAsync(Theme theme)
    {
        CurrentTheme = theme;
        if (_module is not null)
            await _module.InvokeVoidAsync("setTheme", theme.ToString(), AccentColor);
        OnChange?.Invoke();
    }

    public async Task SetAccentColorAsync(string color)
    {
        AccentColor = color;
        if (_module is not null)
            await _module.InvokeVoidAsync("setTheme", CurrentTheme.ToString(), color);
        OnChange?.Invoke();
    }

    public async Task SetAllAsync(Theme theme, string accentColor)
    {
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (_module is not null)
            await _module.InvokeVoidAsync("setTheme", theme.ToString(), accentColor);
        OnChange?.Invoke();
