@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" title="Current theme">
    @GetIcon() @ThemeSvc.CurrentTheme
    @if (!string.IsNullOrEmpty(ThemeSvc.AccentColor))
    {
        <span class="accent-dot" style="background-color: @ThemeSvc.AccentColor;"></span>
    }
</span>

@code {
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            ThemeSvc.OnChange += HandleChange;
            await ThemeSvc.InitializeAsync();
            StateHasChanged();
