toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(ThemeSvc.CurrentTheme == t ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SelectTheme(t)">
                @t
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color"
               value="@(string.IsNullOrEmpty(ThemeSvc.AccentColor) ? "#0d6efd" : ThemeSvc.AccentColor)"
               @onchange="OnAccentChanged"
               class="form-control form-control-color" />
        <span>@(string.IsNullOrEmpty(ThemeSvc.AccentColor) ? "(default)" : ThemeSvc.AccentColor)</span>
    </div>

    <div class="alert alert-info mt-3">
        Active theme: <strong>@ThemeSvc.CurrentTheme</strong> —
        check the header indicator above; it updates in real time.
    </div>
</div>

@code {
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            ThemeSvc.OnChange += HandleChange;
            await ThemeSvc.InitializeAsync();
            StateHasChanged();
        }
    }

    private async Task SelectTheme(Theme theme) => await ThemeSvc.SetThemeAsync(theme);

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString() ?? "";
        await ThemeSvc.SetAccentColorAsync(color);
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnChange -= HandleChange;
}

